void copy_name(const char *input) {
    char name[16];
    strcpy(name, input);
}

fixed_code:
void copy_name(const char *input) {
    char name[16];
    if (input == NULL) return;
    strncpy(name, input, sizeof(name) - 1);
    name[sizeof(name) - 1] = '\0';
}

